// spec: .qa/e2e/specs/journey.md
// seed: tests/seed.user1.spec.ts
import { test, expect, Page } from '@playwright/test';
import * as path from 'path';
import { suppressMilestoneWindow, dismissMilestoneIfShown } from '../_helpers/milestone';

test.use({ storageState: path.resolve(__dirname, '../../../auth/user1.json') });

const ORIGINAL = 'test';
const LOADING = 'טוענים את הקבלה האישית…';

async function gotoJourney(page: Page) {
  await page.goto('/journey');
  const card = page.getByRole('button', { name: /^מקבל על עצמי/ });
  await expect(card).toBeVisible({ timeout: 20_000 });
  await expect(page.getByText(LOADING)).toHaveCount(0, { timeout: 30_000 });
  await dismissMilestoneIfShown(page);
  return card;
}

test.describe('«המסע שלי»', () => {
  test('JR-05 «שמירה» сразу после загрузки не стирает קבלה #31c88137 @data', async ({ page }) => {
    await suppressMilestoneWindow(page); // окно уровня «עלית דרגה» не должно перекрывать экран
    test.setTimeout(120_000);
    const pattern = '**/rest/v1/personal_commitments**';
    try {
      // 1. До перехода: задержка GET personal_commitments 4500 мс.
      await page.route(pattern, async (route) => {
        if (route.request().method() === 'GET') {
          await new Promise((r) => setTimeout(r, 4500));
        }
        await route.continue();
      });

      // 2. Открыть `/journey`; во время «טוענים את הקבלה האישית…» раскрыть «מקבל על עצמי».
      await page.goto('/journey');
      await expect(page.getByText(LOADING)).toBeVisible({ timeout: 20_000 });
      await page.getByRole('button', { name: /^מקבל על עצמי/ }).click();

      // 3. Дождаться значения «test» в поле → сразу «שמירה».
      const field = page.getByRole('textbox', { name: 'מקבל על עצמי' });
      await expect(field).toHaveValue(ORIGINAL, { timeout: 30_000 });
      await expect(page.getByText(LOADING)).toHaveCount(0);
      const save = page.getByRole('button', { name: 'שמירה' });
      const saved = page
        .waitForResponse((r) => r.url().includes('/rest/v1/personal_commitments') && r.request().method() !== 'GET', { timeout: 15_000 })
        .catch(() => null);
      await save.click();
      await saved;

      // 4. `page.unroute`, reload, дождаться исчезновения «טוענים את הקבלה האישית…».
      await page.unroute(pattern);
      const card = await gotoJourney(page);
      await expect(card).toContainText(ORIGINAL);
      await expect(page.getByText('עדיין לא הגדרת קבלה אישית.')).toHaveCount(0);
    } finally {
      // 5. Уборка: если карточка не показывает «test» — раскрыть, ввести «test» → «שמירה» → reload, проверить «test».
      await page.unroute(pattern).catch(() => {});
      const card = await gotoJourney(page);
      if (!(await card.innerText()).includes(ORIGINAL)) {
        await card.click();
        const field = page.getByRole('textbox', { name: 'מקבל על עצמי' });
        await expect(field).toBeEditable();
        await field.fill(ORIGINAL);
        await page.getByRole('button', { name: 'שמירה' }).click();
        await gotoJourney(page);
      }
      await expect(page.getByRole('button', { name: /^מקבל על עצמי/ })).toContainText(ORIGINAL);
    }
  });
});
